package com.example.entity; import jakarta.persistence.*; import java.time.Instant; @Entity @Table(name="stage_questions") public class StageQuestion { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long stageQuestionId; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="stage_session_id", nullable=false) private StageSession stageSession; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="question_id", nullable=false) private Question question; private int questionOrder; private Instant startedAt; private Instant answeredAt; private Instant pausedAt; private long totalPausedMs; public Long getStageQuestionId() { return stageQuestionId; } public void setStageQuestionId(Long id) { this.stageQuestionId = id; } public StageSession getStageSession() { return stageSession; } public void setStageSession(StageSession s) { this.stageSession = s; } public Question getQuestion() { return question; } public void setQuestion(Question q) { this.question = q; } public int getQuestionOrder() { return questionOrder; } public void setQuestionOrder(int o) { this.questionOrder = o; } public Instant getStartedAt() { return startedAt; } public void setStartedAt(Instant s) { this.startedAt = s; } public Instant getAnsweredAt() { return answeredAt; } public void setAnsweredAt(Instant a) { this.answeredAt = a; } public Instant getPausedAt() { return pausedAt; } public void setPausedAt(Instant p) { this.pausedAt = p; } public long getTotalPausedMs() { return totalPausedMs; } public void setTotalPausedMs(long t) { this.totalPausedMs = t; } }
